## Code Example
```javascript
function computeLimit(health, queueLen, sla) {
  const base = 1000;
  if (health > 0.8 && queueLen < sla.maxQueue * 0.7) return Math.min(base * 5, sla.maxCap);
  if (health < 0.4 || queueLen > sla.maxQueue * 0.9) return Math.max(base * 0.2, sla.minCap);
  return base;
}
```

